// Tsat [K] at an ABSOLUTE pressure; returns false (T untouched) outside [kSatP0_Pa, kSatPLast_Pa] or for a non-finite input
inline bool tsatK(float p_abs_Pa, float* T_K) {
  if (!(p_abs_Pa >= kSatP0_Pa && p_abs_Pa <= kSatPLast_Pa)) return false;   // also rejects NaN
  int i = static_cast<int>((p_abs_Pa - kSatP0_Pa) / kSatDp_Pa);
  if (i > kSatN - 2) i = kSatN - 2;
  const float f = (p_abs_Pa - (kSatP0_Pa + static_cast<float>(i) * kSatDp_Pa)) / kSatDp_Pa;
  *T_K = kTsat_K[i] + f * (kTsat_K[i + 1] - kTsat_K[i]);
  return true;
}

